mapper.select:
select id, job_id, article_id, target_code, external_id, external_url, site_url,
       payload_json, result_json, create_by, create_time, update_by, update_time, remark, del_flag
from content_publish_result
where del_flag = '0'

    and article_id = #{articleId}


    and job_id = #{jobId}


    and target_code = #{targetCode}


    and create_time >= #{beginTime}


    and create_time <= #{endTime}

order by create_time desc, id desc
